//! Cache storage implementation.
//!
//! All writes use atomic temp-file-then-rename to prevent torn reads.
//! On Unix, per-entry file locks serialize concurrent access so that
//! content and metadata are always consistent.

use anyhow::{Context, Result};
use sha2::{Digest, Sha256};
use std::fs;
use std::io;
use std::path::{Path, PathBuf};

use super::entry::CacheEntry;

/// Storage for cached templates.
pub struct CacheStore {
    /// Root directory for cache.
    root: PathBuf,
}

/// Write `data` to `path` atomically by writing to a sibling temp file
/// then renaming. On POSIX `rename` is atomic within the same filesystem.
fn atomic_write(path: &Path, data: &[u8]) -> Result<()> {
    let mut tmp_name = path
        .file_name()
        .unwrap_or_default()
