    /// Used by revalidation when content has changed. Caller is
    /// responsible for also calling [`CacheStore::update`] to persist metadata.
    pub fn write_content(&self, source_id: &str, template_name: &str, content: &str) -> Result<()> {
        self.ensure_dir()?;

        let _lock = FileLock::acquire(&self.lock_path(source_id, template_name))?;

        let content_path = self.content_path(source_id, template_name);
        atomic_write(&content_path, content.as_bytes())
    }

    /// Load a cached entry's metadata.
    pub fn load(&self, source_id: &str, template_name: &str) -> Result<Option<CacheEntry>> {
        let meta_path = self.metadata_path(source_id, template_name);

        match fs::read_to_string(&meta_path) {
            Ok(json) => {
                let entry: CacheEntry = serde_json::from_str(&json)?;
                Ok(Some(entry))
            }
            Err(e) if e.kind() == io::ErrorKind::NotFound => Ok(None),
            Err(e) => Err(e).context("failed to read cache metadata"),
        }
    }

    /// Read the cached content.
    pub fn read_content(&self, entry: &CacheEntry) -> Result<String> {
        fs::read_to_string(&entry.content_path).with_context(|| {
            format!(
                "Failed to read cached content from {:?}",
                entry.content_path
            )
        })
    }

    /// Save entry metadata atomically.
    fn save_metadata(&self, entry: &CacheEntry) -> Result<()> {
        let meta_path = self.metadata_path(&entry.source_id, &entry.template_name);
        let json = serde_json::to_string_pretty(entry)?;
        atomic_write(&meta_path, json.as_bytes())
    }

    /// Update an entry's metadata (e.g., after revalidation).
    pub fn update(&self, entry: &CacheEntry) -> Result<()> {
        let _lock = FileLock::acquire(&self.lock_path(&entry.source_id, &entry.template_name))?;
        self.save_metadata(entry)
    }

    /// Remove a cached entry.
    ///
    /// Concurrent removes are safe — `NotFound` errors are ignored.
    pub fn remove(&self, source_id: &str, template_name: &str) -> Result<bool> {
        let _lock = FileLock::acquire(&self.lock_path(source_id, template_name))?;

        let content_path = self.content_path(source_id, template_name);
        let meta_path = self.metadata_path(source_id, template_name);

        let content_removed = remove_if_exists(&content_path)
            .with_context(|| format!("failed to remove {:?}", content_path))?;
        let meta_removed = remove_if_exists(&meta_path)
            .with_context(|| format!("failed to remove {:?}", meta_path))?;

        Ok(content_removed || meta_removed)
    }

    /// List all cached entries.
    pub fn list(&self) -> Result<Vec<CacheEntry>> {
        self.ensure_dir()?;

        let mut entries = Vec::new();

        for entry in fs::read_dir(&self.root)? {
            let entry = entry?;
            let path = entry.path();

            if path.extension().is_some_and(|e| e == "json") {
                if let Ok(json) = fs::read_to_string(&path) {
                    if let Ok(cache_entry) = serde_json::from_str::<CacheEntry>(&json) {
                        entries.push(cache_entry);
                    }
                }
            }
        }

        entries.sort_by(|a, b| b.metadata.cached_at.cmp(&a.metadata.cached_at));
        Ok(entries)
    }

    /// Clear all cached entries.
    pub fn clear(&self) -> Result<usize> {
        let entries = self.list()?;
        let count = entries.len();

        for entry in entries {
            let _ = self.remove(&entry.source_id, &entry.template_name);
        }

        Ok(count)
    }

    /// Get total cache size in bytes.
    pub fn total_size(&self) -> Result<u64> {
        let entries = self.list()?;
        Ok(entries.iter().map(|e| e.metadata.size_bytes).sum())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;

    #[test]
    fn cache_store_creation() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        assert_eq!(store.root(), temp.path());
    }

    #[test]
    fn store_and_load() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let entry = store
            .store("http:test", "template1", "template content", 3600)
            .unwrap();

        assert_eq!(entry.source_id, "http:test");
        assert_eq!(entry.template_name, "template1");

        let loaded = store.load("http:test", "template1").unwrap().unwrap();
        assert_eq!(loaded.source_id, entry.source_id);
        assert_eq!(loaded.template_name, entry.template_name);
    }

    #[test]
    fn read_content() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let entry = store
            .store("http:test", "template1", "hello world", 3600)
            .unwrap();

        let content = store.read_content(&entry).unwrap();
        assert_eq!(content, "hello world");
    }

    #[test]
    fn load_nonexistent_returns_none() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let result = store.load("http:test", "nonexistent").unwrap();
        assert!(result.is_none());
    }

    #[test]
    fn remove_entry() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template1", "content", 3600)
            .unwrap();

        let removed = store.remove("http:test", "template1").unwrap();
        assert!(removed);

        let loaded = store.load("http:test", "template1").unwrap();
        assert!(loaded.is_none());
    }

    #[test]
    fn remove_nonexistent_returns_false() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let removed = store.remove("http:test", "nonexistent").unwrap();
        assert!(!removed);
    }

    #[test]
    fn list_entries() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template1", "content1", 3600)
            .unwrap();
        store
            .store("http:test", "template2", "content2", 3600)
            .unwrap();

        let entries = store.list().unwrap();
        assert_eq!(entries.len(), 2);
    }

    #[test]
    fn clear_cache() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template1", "content1", 3600)
            .unwrap();
        store
            .store("http:test", "template2", "content2", 3600)
            .unwrap();

        let cleared = store.clear().unwrap();
        assert_eq!(cleared, 2);

        let entries = store.list().unwrap();
        assert!(entries.is_empty());
    }

    #[test]
    fn total_size_calculation() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store.store("http:test", "t1", "12345", 3600).unwrap(); // 5 bytes
        store.store("http:test", "t2", "1234567890", 3600).unwrap(); // 10 bytes

        let total = store.total_size().unwrap();
        assert_eq!(total, 15);
    }

    #[test]
    fn content_path_is_deterministic() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let path1 = store.content_path("http:test", "template");
        let path2 = store.content_path("http:test", "template");

        assert_eq!(path1, path2);
    }

    #[test]
    fn different_entries_have_different_paths() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let path1 = store.content_path("http:test", "template1");
        let path2 = store.content_path("http:test", "template2");

        assert_ne!(path1, path2);
    }

    #[test]
    fn concurrent_stores_do_not_corrupt_cache() {
        use std::sync::{Arc, Barrier};
        use std::thread;

        let temp = TempDir::new().unwrap();
        let root = temp.path().to_path_buf();
        let barrier = Arc::new(Barrier::new(10));

        let handles: Vec<_> = (0..10)
            .map(|i| {
                let root = root.clone();
                let barrier = barrier.clone();
                thread::spawn(move || {
                    let store = CacheStore::new(&root);
                    barrier.wait();
                    let content = format!("content-from-thread-{}", i);
                    store
                        .store("http:test", "shared-template", &content, 3600)
                        .unwrap();
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }

        // After all threads finish, cache should contain valid (non-corrupted) data
        let store = CacheStore::new(temp.path());
        let entry = store.load("http:test", "shared-template").unwrap().unwrap();
        let content = store.read_content(&entry).unwrap();

        // Content must be from exactly one thread, not a corrupted mix
        assert!(
            content.starts_with("content-from-thread-"),
            "content was corrupted: {:?}",
            content
        );

        // Metadata must be valid and consistent
        assert_eq!(entry.source_id, "http:test");
        assert_eq!(entry.template_name, "shared-template");
        assert_eq!(entry.metadata.size_bytes, content.len() as u64);
    }

    #[test]
    fn concurrent_removes_do_not_error() {
        use std::sync::{Arc, Barrier};
        use std::thread;

        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());
        store
            .store("http:test", "template", "content", 3600)
            .unwrap();

        let root = temp.path().to_path_buf();
        let barrier = Arc::new(Barrier::new(5));

        let handles: Vec<_> = (0..5)
            .map(|_| {
                let root = root.clone();
                let barrier = barrier.clone();
                thread::spawn(move || {
                    let store = CacheStore::new(&root);
                    barrier.wait();
                    store.remove("http:test", "template")
                })
            })
            .collect();

        let mut any_removed = false;
        for h in handles {
            // No thread should panic or return an error
            match h.join().unwrap() {
                Ok(removed) => {
                    if removed {
                        any_removed = true;
                    }
                }
                Err(e) => panic!("concurrent remove returned error: {}", e),
            }
        }

        assert!(any_removed, "at least one thread should report removal");

        // Entry should be gone
        let loaded = store.load("http:test", "template").unwrap();
        assert!(loaded.is_none());
    }

    #[test]
    fn concurrent_store_and_read_no_partial_content() {
        use std::sync::{Arc, Barrier};
        use std::thread;

        let temp = TempDir::new().unwrap();
        let root = temp.path().to_path_buf();
        let barrier = Arc::new(Barrier::new(6));

        // 3 writers
        let mut handles: Vec<_> = (0..3)
            .map(|i| {
                let root = root.clone();
                let barrier = barrier.clone();
                thread::spawn(move || {
                    let store = CacheStore::new(&root);
                    barrier.wait();
                    let content = "X".repeat(1000 * (i + 1));
                    for _ in 0..20 {
                        let _ = store.store("http:test", "rw-template", &content, 3600);
                    }
                })
            })
            .collect();

        // 3 readers
        for _ in 0..3 {
            let root = root.clone();
            let barrier = barrier.clone();
            handles.push(thread::spawn(move || {
                let store = CacheStore::new(&root);
                barrier.wait();
                for _ in 0..20 {
                    if let Ok(Some(entry)) = store.load("http:test", "rw-template") {
                        if let Ok(content) = store.read_content(&entry) {
                            // Content should be all the same character (not a mix
                            // of two partially-written values)
                            let bytes = content.as_bytes();
                            if !bytes.is_empty() {
                                let first = bytes[0];
                                assert!(
                                    bytes.iter().all(|&b| b == first),
                                    "read partial/corrupted content: different bytes found"
                                );
                            }
                        }
                        // Errors from read_content are OK (file may have been
                        // swapped between load and read)
                    }
                }
            }));
        }

        for h in handles {
            h.join().unwrap();
        }
    }
}

