        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let path1 = store.content_path("http:test", "template");
        let path2 = store.content_path("http:test", "template");

        assert_eq!(path1, path2);
    }

    #[test]
    fn different_entries_have_different_paths() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let path1 = store.content_path("http:test", "template1");
        let path2 = store.content_path("http:test", "template2");

        assert_ne!(path1, path2);
    }

    #[test]
    fn concurrent_stores_do_not_corrupt_cache() {
        use std::sync::{Arc, Barrier};
        use std::thread;

        let temp = TempDir::new().unwrap();
        let root = temp.path().to_path_buf();
        let barrier = Arc::new(Barrier::new(10));

        let handles: Vec<_> = (0..10)
            .map(|i| {
                let root = root.clone();
                let barrier = barrier.clone();
                thread::spawn(move || {
                    let store = CacheStore::new(&root);
                    barrier.wait();
                    let content = format!("content-from-thread-{}", i);
                    store
                        .store("http:test", "shared-template", &content, 3600)
                        .unwrap();
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }

        // After all threads finish, cache should contain valid (non-corrupted) data
        let store = CacheStore::new(temp.path());
        let entry = store.load("http:test", "shared-template").unwrap().unwrap();
        let content = store.read_content(&entry).unwrap();

        // Content must be from exactly one thread, not a corrupted mix
        assert!(
            content.starts_with("content-from-thread-"),
            "content was corrupted: {:?}",
            content
        );

        // Metadata must be valid and consistent
        assert_eq!(entry.source_id, "http:test");
        assert_eq!(entry.template_name, "shared-template");
        assert_eq!(entry.metadata.size_bytes, content.len() as u64);
    }

    #[test]
    fn concurrent_removes_do_not_error() {
        use std::sync::{Arc, Barrier};
        use std::thread;

        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());
        store
            .store("http:test", "template", "content", 3600)
            .unwrap();

        let root = temp.path().to_path_buf();
        let barrier = Arc::new(Barrier::new(5));

        let handles: Vec<_> = (0..5)
            .map(|_| {
                let root = root.clone();
                let barrier = barrier.clone();
                thread::spawn(move || {
                    let store = CacheStore::new(&root);
                    barrier.wait();
                    store.remove("http:test", "template")
                })
            })
            .collect();

        let mut any_removed = false;
        for h in handles {
            // No thread should panic or return an error
            match h.join().unwrap() {
                Ok(removed) => {
                    if removed {
                        any_removed = true;
                    }
                }
                Err(e) => panic!("concurrent remove returned error: {}", e),
            }
        }

        assert!(any_removed, "at least one thread should report removal");

        // Entry should be gone
        let loaded = store.load("http:test", "template").unwrap();
        assert!(loaded.is_none());
    }

    #[test]
    fn concurrent_store_and_read_no_partial_content() {
        use std::sync::{Arc, Barrier};
        use std::thread;

        let temp = TempDir::new().unwrap();
        let root = temp.path().to_path_buf();
        let barrier = Arc::new(Barrier::new(6));

        // 3 writers
        let mut handles: Vec<_> = (0..3)
            .map(|i| {
                let root = root.clone();
                let barrier = barrier.clone();
                thread::spawn(move || {
                    let store = CacheStore::new(&root);
                    barrier.wait();
                    let content = "X".repeat(1000 * (i + 1));
                    for _ in 0..20 {
                        let _ = store.store("http:test", "rw-template", &content, 3600);
                    }
                })
            })
            .collect();

        // 3 readers
        for _ in 0..3 {
            let root = root.clone();
            let barrier = barrier.clone();
            handles.push(thread::spawn(move || {
                let store = CacheStore::new(&root);
                barrier.wait();
                for _ in 0..20 {
                    if let Ok(Some(entry)) = store.load("http:test", "rw-template") {
                        if let Ok(content) = store.read_content(&entry) {
                            // Content should be all the same character (not a mix
                            // of two partially-written values)
                            let bytes = content.as_bytes();
                            if !bytes.is_empty() {
                                let first = bytes[0];
                                assert!(
                                    bytes.iter().all(|&b| b == first),
                                    "read partial/corrupted content: different bytes found"
                                );
                            }
                        }
                        // Errors from read_content are OK (file may have been
                        // swapped between load and read)
                    }
                }
            }));
        }

        for h in handles {
            h.join().unwrap();
        }
    }
}

