//! Cache storage implementation.
//!
//! All writes use atomic temp-file-then-rename to prevent torn reads.
//! On Unix, per-entry file locks serialize concurrent access so that
//! content and metadata are always consistent.

use anyhow::{Context, Result};
use sha2::{Digest, Sha256};
use std::fs;
use std::io;
use std::path::{Path, PathBuf};

use super::entry::CacheEntry;

/// Storage for cached templates.
pub struct CacheStore {
    /// Root directory for cache.
    root: PathBuf,
}

/// Write `data` to `path` atomically by writing to a sibling temp file
/// then renaming. On POSIX `rename` is atomic within the same filesystem.
fn atomic_write(path: &Path, data: &[u8]) -> Result<()> {
    let mut tmp_name = path
        .file_name()
        .unwrap_or_default()
        .to_os_string();
    let mut rand_buf = [0u8; 8];
    getrandom::fill(&mut rand_buf).context("failed to generate random bytes for temp file")?;
    tmp_name.push(format!(".{}.tmp", hex::encode(rand_buf)));
    let tmp_path = path.with_file_name(tmp_name);

    fs::write(&tmp_path, data)
        .with_context(|| format!("failed to write temp file {:?}", tmp_path))?;

    fs::rename(&tmp_path, path).map_err(|e| {
        let _ = fs::remove_file(&tmp_path);
        e
    }).with_context(|| format!("failed to rename temp file to {:?}", path))?;

    Ok(())
}

/// Try to remove a file, treating `NotFound` as success.
fn remove_if_exists(path: &Path) -> io::Result<bool> {
    match fs::remove_file(path) {
        Ok(()) => Ok(true),
        Err(e) if e.kind() == io::ErrorKind::NotFound => Ok(false),
        Err(e) => Err(e),
    }
}

// --- Per-entry file locking (Unix) ---

#[cfg(unix)]
mod lock {
    use anyhow::{Context, Result};
    use std::fs;
    use std::os::unix::io::AsRawFd;
    use std::path::Path;

    /// RAII advisory file lock using `flock(2)`.
    pub(super) struct FileLock {
        _file: fs::File,
    }

    impl FileLock {
        /// Acquire an exclusive lock, blocking until available.
        pub fn acquire(path: &Path) -> Result<Self> {
            let file = fs::OpenOptions::new()
                .create(true)
                .truncate(false)
                .write(true)
                .open(path)
                .with_context(|| format!("failed to open lock file {:?}", path))?;

            let ret = unsafe { libc::flock(file.as_raw_fd(), libc::LOCK_EX) };
            if ret != 0 {
                let err = std::io::Error::last_os_error();
                anyhow::bail!("flock failed on {:?}: {}", path, err);
            }

            Ok(Self { _file: file })
        }
    }

    // flock is released automatically when the file descriptor is closed,
    // which happens when `_file` is dropped.
}

#[cfg(not(unix))]
mod lock {
    use anyhow::Result;
    use std::path::Path;

    /// No-op lock on non-Unix platforms. Atomic writes still protect
    /// against torn reads, but not against interleaved content/metadata.
    pub(super) struct FileLock;

    impl FileLock {
        pub fn acquire(_path: &Path) -> Result<Self> {
            Ok(Self)
        }
    }
}

use lock::FileLock;

impl CacheStore {
    /// Create a new cache store.
    pub fn new(root: impl Into<PathBuf>) -> Self {
        Self { root: root.into() }
    }

    /// Get the cache root directory.
    pub fn root(&self) -> &Path {
        &self.root
    }

    /// Ensure the cache directory exists.
    fn ensure_dir(&self) -> Result<()> {
        fs::create_dir_all(&self.root)
            .with_context(|| format!("Failed to create cache directory {:?}", self.root))
    }

    /// Get the path for storing an entry's content.
    pub fn content_path(&self, source_id: &str, template_name: &str) -> PathBuf {
        let key = format!("{}:{}", source_id, template_name);
        let hash = Sha256::digest(key.as_bytes());
        let hash_str = hex::encode(&hash[..16]);
        self.root.join(hash_str)
    }

    /// Get the metadata file path for an entry.
    fn metadata_path(&self, source_id: &str, template_name: &str) -> PathBuf {
        self.content_path(source_id, template_name)
            .with_extension("meta.json")
    }

    /// Get the lock file path for an entry.
    fn lock_path(&self, source_id: &str, template_name: &str) -> PathBuf {
        self.content_path(source_id, template_name)
            .with_extension("lock")
    }

    /// Store content and return a cache entry.
    ///
    /// Acquires a per-entry lock, then writes content and metadata
    /// atomically so concurrent processes never see partial state.
    pub fn store(
        &self,
        source_id: &str,
        template_name: &str,
        content: &str,
        ttl_seconds: u64,
    ) -> Result<CacheEntry> {
        self.ensure_dir()?;

        let _lock = FileLock::acquire(&self.lock_path(source_id, template_name))?;

        let content_path = self.content_path(source_id, template_name);
        atomic_write(&content_path, content.as_bytes())?;

        let entry = CacheEntry::new(source_id, template_name, &content_path, ttl_seconds)
            .with_size(content.len() as u64);

        self.save_metadata(&entry)?;

        Ok(entry)
    }

    /// Write content to the cache for an existing entry.
    ///
    /// Used by revalidation when content has changed. Caller is
    /// responsible for also calling [`update`] to persist metadata.
    pub fn write_content(&self, source_id: &str, template_name: &str, content: &str) -> Result<()> {
        self.ensure_dir()?;

        let _lock = FileLock::acquire(&self.lock_path(source_id, template_name))?;

        let content_path = self.content_path(source_id, template_name);
        atomic_write(&content_path, content.as_bytes())
    }

    /// Load a cached entry's metadata.
    pub fn load(&self, source_id: &str, template_name: &str) -> Result<Option<CacheEntry>> {
        let meta_path = self.metadata_path(source_id, template_name);

        match fs::read_to_string(&meta_path) {
            Ok(json) => {
                let entry: CacheEntry = serde_json::from_str(&json)?;
                Ok(Some(entry))
            }
            Err(e) if e.kind() == io::ErrorKind::NotFound => Ok(None),
            Err(e) => Err(e).context("failed to read cache metadata"),
        }
    }

    /// Read the cached content.
    pub fn read_content(&self, entry: &CacheEntry) -> Result<String> {
        fs::read_to_string(&entry.content_path).with_context(|| {
            format!(
                "Failed to read cached content from {:?}",
                entry.content_path
            )
        })
    }

    /// Save entry metadata atomically.
    fn save_metadata(&self, entry: &CacheEntry) -> Result<()> {
        let meta_path = self.metadata_path(&entry.source_id, &entry.template_name);
        let json = serde_json::to_string_pretty(entry)?;
        atomic_write(&meta_path, json.as_bytes())
    }

    /// Update an entry's metadata (e.g., after revalidation).
    pub fn update(&self, entry: &CacheEntry) -> Result<()> {
        let _lock = FileLock::acquire(
            &self.lock_path(&entry.source_id, &entry.template_name),
        )?;
        self.save_metadata(entry)
    }

    /// Remove a cached entry.
    ///
    /// Concurrent removes are safe — `NotFound` errors are ignored.
    pub fn remove(&self, source_id: &str, template_name: &str) -> Result<bool> {
        let _lock = FileLock::acquire(&self.lock_path(source_id, template_name))?;

        let content_path = self.content_path(source_id, template_name);
        let meta_path = self.metadata_path(source_id, template_name);

        let content_removed = remove_if_exists(&content_path)
            .with_context(|| format!("failed to remove {:?}", content_path))?;
        let meta_removed = remove_if_exists(&meta_path)
            .with_context(|| format!("failed to remove {:?}", meta_path))?;

        Ok(content_removed || meta_removed)
    }

    /// List all cached entries.
    pub fn list(&self) -> Result<Vec<CacheEntry>> {
        self.ensure_dir()?;

        let mut entries = Vec::new();

        for entry in fs::read_dir(&self.root)? {
            let entry = entry?;
            let path = entry.path();

            if path.extension().is_some_and(|e| e == "json") {
                if let Ok(json) = fs::read_to_string(&path) {
                    if let Ok(cache_entry) = serde_json::from_str::<CacheEntry>(&json) {
                        entries.push(cache_entry);
                    }
                }
            }
        }

        entries.sort_by(|a, b| b.metadata.cached_at.cmp(&a.metadata.cached_at));
        Ok(entries)
    }

    /// Clear all cached entries.
    pub fn clear(&self) -> Result<usize> {
        let entries = self.list()?;
        let count = entries.len();

        for entry in entries {
            let _ = self.remove(&entry.source_id, &entry.template_name);
        }

        Ok(count)
    }

    /// Get total cache size in bytes.
    pub fn total_size(&self) -> Result<u64> {
        let entries = self.list()?;
        Ok(entries.iter().map(|e| e.metadata.size_bytes).sum())
    }
}

